 update public.hr_roles set work_content=coalesce(work_content,'{}')||'{"interview_questionnaire_draft":{"version":1,"revision":1,"status":"draft","origin":"propuesta basada en contenido verificado de la plaza","review_note":"Propuesta automática pendiente de revisión y aprobación. No activa en entrevistas.","questions":[{"id":"iq_b1d97ac2bbc66eb8","section":"Recepción del cliente","text":"Un cliente solicita un servicio, pero faltan materiales y no están claros los entregables. ¿Qué preguntarías y registrarías antes de comprometer una fecha?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.atencion-cliente","sha256":"d4a6fb3f9ad14770a32e08daa84c20c8971b3a339889b9311cbc5b347116b56e"}},{"id":"iq_f8d9bc4880bfcc87","section":"Prioridades","text":"Tienes una entrega próxima, materiales pendientes de otro cliente y un especialista bloqueado. ¿Cómo determinarías el orden de atención y qué elevarías al Jefe de Área?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.prioridades","sha256":"c7877210e300efb64ad25dd643b13047379377a16c199c21342a06bff87ad483"}},{"id":"iq_f9d49ee999b6183e","section":"Coordinación","text":"Un especialista comunica que no llegará al plazo acordado. ¿Qué comprobarías, qué alternativas prepararías y quién debe aprobar cambios del calendario?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.coordinar-especialistas","sha256":"ecf052b3bc6dda81eca9b5782bbadb2ae6cb0124f107dd8b10ba9e73d972f8cf"}},{"id":"iq_3e3216bdfcfaf049","section":"Límites comerciales","text":"Un cliente pide un descuento y un entregable adicional durante el proyecto. Formula la respuesta inicial y explica el proceso para obtener y registrar la decisión.","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.compromisos-comerciales","sha256":"c0aee892efc5722fda11ef0429dffb688070d308d87a9afa024f55b84b1b8490"}},{"id":"iq_3de403c02bb9a1af","section":"Finanzas","text":"El cliente envía un comprobante y pide que confirmes que el servicio está pagado. ¿Qué verificarías con Finanzas antes de actualizar el expediente?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.compromisos-comerciales","sha256":"c0aee892efc5722fda11ef0429dffb688070d308d87a9afa024f55b84b1b8490"}},{"id":"iq_0e9cf79640e3ce74","section":"Incidencias","text":"Un archivo necesario para una entrega no abre. Explica cómo protegerías originales y respaldos, a quién acudirías y qué registrarías sobre la incidencia.","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.imprevistos","sha256":"da54b2151bc9dce470d36b7883d17f1c80043cb831604ad43ef9922f72a0d430"}},{"id":"iq_b22c3182e02080be","section":"Cierre del proyecto","text":"Un especialista dice que terminó. ¿Qué revisarías antes de entregar, confirmar recepción y proponer el cierre del expediente?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.cierre-proyecto","sha256":"83681da5a4f8272bb7b8ba25a87751e951128302a70498dc84f3cdbdfb0bd758"}},{"id":"iq_6f7f3e460719ce26","section":"Trazabilidad","text":"Un acuerdo importante se tomó por teléfono y contradice un mensaje anterior. ¿Cómo verificarías la información y dejarías una constancia útil para el equipo?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.control-informacion","sha256":"f6ac0d50243ef5c6a22568f6cae93eeda516c1158f0cc86a6bde62acf2439671"}},{"id":"iq_2a2ea413b7c0bb2e","section":"Prevención","text":"Una producción se aproxima con equipos sin confirmar y una aprobación pendiente. ¿Cómo registrarías el riesgo y coordinarías las próximas acciones?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.gestion-riesgos","sha256":"bc1df0e99b8d88f0f2463502a34b4f51a0f2bfd84bfa7879131969cf0695a5d7"}},{"id":"iq_18ad2ea267dbadeb","section":"Continuidad","text":"Mañana te ausentas y quedan proyectos en curso. ¿Qué información prepararías para que la persona designada continúe sin depender de tus chats privados?","help":"Solicitar pasos concretos, criterios y un ejemplo; contrastar con las responsabilidades vigentes de la plaza.","type":"text","required":true,"options":[],"source":{"path":"work_content.custom.continuidad-operativa","sha256":"a16554b27262e0d3c869da1bee35dc4ac5eef91f46a0e2867e19e474a93fc8c0"}}]}}'::jsonb,updated_at=clock_timestamp() where title='Gestor Operativo' and not (coalesce(work_content,'{}') ? 'interview_questionnaire_draft') and not (coalesce(work_content,'{}') ? 'interview_questionnaire_published');
